64	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
65	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
66	  // `BootSplashScreen`.
67	  static const _skeletonThreshold = Duration(milliseconds: 300);
68	
69	  final ScrollController _scrollController = ScrollController();
70	  Timer? _skeletonTimer;
71	  bool _showSkeleton = false;
72	
73	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
74	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
75	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
76	  /// `MeusRegistrosLoading`: started fresh on every transition into
77	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
78	  /// first-load timer above (started once, in [initState]) a search can
79	  /// enter/leave loading many times across one screen visit.
80	  Timer? _searchSkeletonTimer;
81	  bool _showSearchSkeleton = false;
82	
83	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
84	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
85	  /// detail-route instances); cleared once the pushed route is popped, via
86	  /// `whenComplete` below.
87	  bool _navigatingToDetail = false;
88	
89	  /// Review finding (edge-case-hunter layer, spec-7-1) — same rationale as
90	  /// [_navigatingToDetail] above, for `_onExportTap`: guards against a
91	  /// rapid double-tap on the export icon opening a second
92	  /// `showDateRangePicker`/creating a second job while the first tap's own
93	  /// awaited chain is still in flight. Cleared in every exit path of
94	  /// `_onExportTap` (`finally`).
95	  bool _exportInFlight = false;
96	
97	  @override
98	  void initState() {
99	    super.initState();
100	    widget.cubit.loadFirstPage();
101	    // spec-5-3 — both `cubit`/`searchCubit` are `lazySingleton`s (Code
102	    // Map): a fresh mount of this screen must reset both, not just
103	    // `cubit`'s own filters above, or a re-entered screen would carry a
104	    // stale filter selection from a previous visit into a still-active
105	    // search (Boundaries: "Re-enter screen after a prior combined
106	    // session").
107	    widget.searchCubit.updateFilters(
108	      source: null,
109	      dateFrom: null,
110	      dateTo: null,
111	    );
112	    _skeletonTimer = Timer(_skeletonThreshold, () {
113	      if (mounted) {
114	        setState(() => _showSkeleton = true);
115	      }
116	    });
117	    _scrollController.addListener(_onScroll);
118	    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
119	    // that can already be `ResourceLoading` the moment this `State` is
120	    // (re)created — e.g. the user switches tabs away mid-search and back,
121	    // which tears down and rebuilds this plain `GoRoute`'s widget while the
122	    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
123	    // only fires on a *new* state, never for one already current at
124	    // subscription time, so without this check the search skeleton would
125	    // never arm for an in-flight search resumed this way.
126	    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
127	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
128	        if (mounted) {
129	          setState(() => _showSearchSkeleton = true);
130	        }
131	      });
132	    }
133	  }
134	
135	  @override
136	  void dispose() {
137	    _skeletonTimer?.cancel();
138	    _searchSkeletonTimer?.cancel();
139	    _scrollController
140	      ..removeListener(_onScroll)
141	      ..dispose();
142	    super.dispose();
143	  }
144	
145	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
146	  /// [_searchSkeletonTimer] fresh on every transition into
147	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
148	  /// but re-armed per search rather than once per screen visit; any other
149	  /// state (including a fast resolve before the 300ms threshold, RNF01)
150	  /// cancels it and resets [_showSearchSkeleton].
151	  void _onSearchStateChanged(
152	    BuildContext context,
153	    Resource<List<Entry>> state,
154	  ) {
155	    _searchSkeletonTimer?.cancel();
156	    if (state is ResourceLoading<List<Entry>>) {
157	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
158	        if (mounted) {
159	          setState(() => _showSearchSkeleton = true);
160	        }
161	      });
162	      return;
163	    }
164	    if (_showSearchSkeleton) {
165	      setState(() => _showSearchSkeleton = false);
166	    }
167	  }
168	
169	  void _openDetail(Entry entry) {
170	    if (_navigatingToDetail) {
171	      return;
172	    }
173	    _navigatingToDetail = true;
174	    context
175	        .push(
176	          '${AppRoutePaths.meusRegistros}/'
177	          '${Uri.encodeComponent(entry.id)}',
178	        )
179	        .whenComplete(() {
180	          if (mounted) {
