8	/// in-app webview, which would effectively buffer the file instead of
9	/// handing it off (Boundaries).
10	class UrlLauncherDownloadOpener implements DownloadOpener {
11	  @override
12	  Future<bool> open(String url) async {
13	    try {
14	      return await launchUrl(
15	        Uri.parse(url),
16	        mode: LaunchMode.externalApplication,
17	      );
18	    } catch (_) {
19	      // A malformed URL (`Uri.parse`) or a platform-channel failure
20	      // (`launchUrl`) must never crash the cubit's own download flow
21	      // (RNF09) — both degrade to the same "couldn't open it" signal a
22	      // plain `false` already carries.
23	      return false;
24	    }
25	  }
26	}
